using ClosedXML.Excel;using Microsoft.EntityFrameworkCore;using System.IO.Compression;using System.Text;
namespace Decont;
public static class Documents {
 public static void Map(RouteGroupBuilder api){
 api.MapGet("/reports/{id:guid}/erp-preview",async(Guid id,Reports svc,Db db,Posting posting,HttpContext c)=>{var r=await svc.Get(id,c.User);var issues=await svc.Validate(r,true);if(issues.Any(x=>x.Blocking))return Results.Ok(new{headers=Posting.Headers,issues,rows=Array.Empty<string[]>()});var user=await db.Users.FindAsync(r.EmployeeId);var result=posting.Build(r,user!,await db.Masters.ToListAsync());return Results.Ok(new{headers=Posting.Headers,issues,rows=result.Rows,version=result.Version});}).RequireAuthorization(p=>p.RequireRole("Finance","Auditor"));
 api.MapGet("/batches/{id:guid}/xlsx",async(Guid id,Db db,Reports svc,IStore store,HttpContext c)=>{var b=await db.Batches.SingleOrDefaultAsync(b=>b.Id==id)??throw new DomainException("missing","Export inexistent.","Batch not found.",404);await svc.Get(b.ReportId,c.User);Guard.Require(b.Hash==Serialization.Hash(b.Rows),"integrity","Integritatea exportului este invalidă.","Batch integrity check failed.");var file=await store.Get(b.Key);Guard.Require(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(file))==b.FileHash,"integrity","Integritatea fișierului este invalidă.","File integrity check failed.");svc.Log(c.User,b.ReportId,b.Id.ToString(),"BatchDownloaded",after:b.Hash);await db.SaveChangesAsync();return Results.File(file,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"Import-{b.Id}.xlsx");}).RequireAuthorization(p=>p.RequireRole("Finance","Auditor"));
 api.MapGet("/reports/{id:guid}/pdf",async(Guid id,Db db,Reports svc,HttpContext c)=>{var r=await svc.Get(id,c.User);var employee=await db.Users.SingleAsync(u=>u.Id==r.EmployeeId);var bytes=ReportPdf.Generate(r,employee,await db.Decisions.Where(d=>d.ReportId==id).ToListAsync());svc.Log(c.User,id,"Report","PDFDownloaded");await db.SaveChangesAsync();return Results.File(bytes,"application/pdf",r.Number+".pdf");});
 api.MapGet("/reports/{id:guid}/pack",async(Guid id,Db db,Reports svc,IStore store,HttpContext c)=>{var r=await svc.Get(id,c.User);using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){async Task Write(string name,byte[] bytes){var entry=zip.CreateEntry(name,CompressionLevel.Fastest);await using var s=entry.Open();await s.WriteAsync(bytes);}await Write("report.json",Encoding.UTF8.GetBytes(Serialization.Write(Api.View(r))));await Write("report.html",Encoding.UTF8.GetBytes(Html(r)));await Write("report.pdf",ReportPdf.Generate(r,await db.Users.SingleAsync(u=>u.Id==r.EmployeeId),await db.Decisions.Where(d=>d.ReportId==id).ToListAsync()));await Write("snapshots.json",Encoding.UTF8.GetBytes(Serialization.Write(await db.Snapshots.Where(s=>s.ReportId==id).ToListAsync())));await Write("audit.json",Encoding.UTF8.GetBytes(Serialization.Write(await db.Audits.Where(a=>a.ReportId==id).ToListAsync())));var docs=r.Lines.SelectMany(l=>l.Evidence).Where(e=>e.Scan=="Clean").ToList();await Write("manifest.json",Encoding.UTF8.GetBytes(Serialization.Write(docs.Select(e=>new{e.Id,e.Name,e.Hash,e.Size,e.Archived}))));foreach(var e in docs){var bytes=await store.Get(e.Key);Guard.Require(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes))==e.Hash,"integrity","Integritatea documentului este invalidă.","Document integrity check failed.");await Write("originals/"+e.Id+Path.GetExtension(e.Name),bytes);}}svc.Log(c.User,id,"Report","PackDownloaded");await db.SaveChangesAsync();return Results.File(output.ToArray(),"application/zip",r.Number+".zip");});
 api.MapGet("/reports/{id:guid}/print",async(Guid id,Reports svc,HttpContext c)=>Results.Content(Html(await svc.Get(id,c.User)),"text/html",Encoding.UTF8));
 api.MapGet("/analytics",async(Reports svc,HttpContext c)=>{var rows=await svc.Scope(c.User).Include(r=>r.Lines).ToListAsync();return new{reports=rows.Count,total=rows.Sum(r=>r.Lines.Where(l=>!l.Archived).Sum(l=>l.Final())),states=rows.GroupBy(r=>r.State).Select(g=>new{state=g.Key,count=g.Count()}),categories=rows.SelectMany(r=>r.Lines.Where(l=>!l.Archived)).GroupBy(l=>l.Data().Category).Select(g=>new{category=g.Key,total=g.Sum(l=>l.Final())})};});
 api.MapGet("/analytics/csv",async(Reports svc,Db db,HttpContext c)=>{var rows=await svc.Scope(c.User).Include(r=>r.Lines).ToListAsync();var csv="Report,Employee,State,Created,Category,CostCenter,Project,Payment,Currency,Amount,FinalRON\r\n"+string.Join("\r\n",rows.SelectMany(r=>r.Lines.Where(l=>!l.Archived).Select(l=>{var d=l.Data();return string.Join(",",new object?[]{r.Number,r.EmployeeId,r.State,r.Created.ToString("O"),d.Category,d.CostCenter,d.Project,d.Payment,d.Currency,d.Amount,l.Final()}.Select(Csv.Cell));})));svc.Log(c.User,null,"Analytics","CSVDownloaded",after:new{reports=rows.Count});await db.SaveChangesAsync();return Results.File(Encoding.UTF8.GetBytes("\uFEFF"+csv),"text/csv","decont-raport.csv");}).RequireAuthorization(p=>p.RequireRole("Finance","Admin","Auditor"));
 }
 public static byte[] Workbook(List<string[]> rows){using var book=new XLWorkbook();var sheet=book.AddWorksheet("Import");for(int j=0;j<24;j++)sheet.Cell(1,j+1).Value=Posting.Headers[j];for(int j=0;j<rows.Count;j++)for(int k=0;k<24;k++){if((k is 13 or 14)&&decimal.TryParse(rows[j][k],System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var amount))sheet.Cell(j+2,k+1).Value=amount;else sheet.Cell(j+2,k+1).Value=rows[j][k];}sheet.Columns().AdjustToContents();using var output=new MemoryStream();book.SaveAs(output);return output.ToArray();}
 public static string Html(Report r){string E(object? s)=>System.Net.WebUtility.HtmlEncode(Convert.ToString(s,System.Globalization.CultureInfo.InvariantCulture))??"";return "<!doctype html><html lang='ro'><meta charset='utf-8'><title>"+E(r.Number)+"</title><style>body{font:14px system-ui;margin:40px;color:#132e2a}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}h1{color:#096655}@media print{button{display:none}tr{break-inside:avoid}}</style><button onclick='window.print()'>Tipărește / Save PDF</button><h1>Decont de cheltuieli / Expense report</h1><p>"+E(r.Number)+" · "+E(r.State)+" · Revizia / Revision "+r.Revision+"</p><h2>"+E(r.Purpose)+"</h2><table><thead><tr><th>Data / Date<th>Furnizor / Supplier<th>Document<th>Descriere / Description<th>RON</thead><tbody>"+string.Join("",r.Lines.Where(l=>!l.Archived).Select(l=>{var d=l.Data();return "<tr><td>"+E(d.Date)+"<td>"+E(d.Supplier)+"<td>"+E(d.Invoice)+"<td>"+E(d.Description)+"<td>"+E(l.Final());}))+"</tbody></table><h2>Total: "+E(r.Lines.Where(l=>!l.Archived).Sum(l=>l.Final()))+" RON</h2><p>Rambursare personală / Personal reimbursement: "+E(Rules.Personal(r))+" RON</p></html>";}
}
